WITH cleaned AS (SELECT id, device_code, reading_ts, status_bits, CAST(pressure AS INT) AS pressure_int, SUBSTRING(device_code, 1, 3) AS device_code_prefix FROM device_readings WHERE status_bits >= 9), prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM cleaned), gaps AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_no, CASE WHEN session_no >= 7 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(pressure_int), 2) AS avg_pressure_int, ROUND(SUM(status_bits) / NULLIF(COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END), 0), 2) AS status_bits_per_dv_03, PERCENT_RANK() OVER (PARTITION BY session_no ORDER BY ROUND(AVG(pressure_int), 2) DESC) AS avg_pressure_int_percent_rank FROM sessions_device_readings GROUP BY 1, 2 ORDER BY distinct_ids NULLS FIRST;
